					t.Fatal("cleanup did not run", e)
				}
			} else {
				if e != nil || summary["outcome"] != "PASS" {
					t.Fatal(summary, e)
				}
				if !slices.Equal(calls[:7], []string{"recheck_inputs", "copy_images", "network", "start_rustfs", "stage_a", "stage_b", "start_vms"}) {
					t.Fatal(calls)
				}
			}
		})
	}
}

