func LoadManagedManifest(path string) (ManagedManifest, error) {
	var manifest ManagedManifest
	raw, e := os.ReadFile(path)
	if e != nil {
		return manifest, e
	}
	if len(raw) > 64<<10 {
		return manifest, errors.New("manifest exceeds 64 KiB")
	}
	v, e := decodeStrict(raw)
	if e != nil {
		return manifest, e
	}
	m := object(v)
	if !exactFields(m, []string{"profile", "source_commits", "inputs", "members"}) || m["profile"] != ManagedMemberProfile {
		return manifest, errors.New("unsupported or malformed qualification manifest")
	}
	commits := object(m["source_commits"])
	if !exactFields(commits, []string{"orchestrator", "terrabase"}) || !commitPattern.MatchString(str(commits["orchestrator"])) || !commitPattern.MatchString(str(commits["terrabase"])) {
		return manifest, errors.New("source commits must be full hexadecimal IDs")
	}
	common, members := object(m["inputs"]), object(m["members"])
	if !exactFields(common, ManagedCommonInputs) || !exactFields(members, []string{"a", "b"}) {
		return manifest, errors.New("manifest has missing or extra common/member inputs")
	}
	manifest = ManagedManifest{Raw: raw, SHA256: hashBytes(raw), Commits: commits, Inputs: map[string]ManagedInput{}, Members: map[string]ManagedMember{}}
	for _, name := range ManagedCommonInputs {
		input, e := ExactManagedInput(name, object(common[name]))
		if e != nil {
			return manifest, e
		}
		if slices.Contains([]string{"firecracker", "go_host_test", "tb_server"}, name) {
			if e := unix.Access(input.Path, unix.X_OK); e != nil {
				return manifest, fmt.Errorf("%s: input must be executable", name)
			}
		}
		manifest.Inputs[name] = input
	}
	for _, member := range []string{"a", "b"} {
		record := object(members[member])
		if !exactFields(record, []string{"inputs", "guest_config"}) || !exactFields(object(record["inputs"]), ManagedMemberInputs) {
			return manifest, fmt.Errorf("%s: input names are incomplete", member)
		}
		inputs := map[string]ManagedInput{}
		for _, name := range ManagedMemberInputs {
			r, e := ExactManagedInput(member+"."+name, object(object(record["inputs"])[name]))
			if e != nil {
				return manifest, e
			}
			inputs[name] = r
		}
		if inputs["volume_ext4"].Size != 256<<20 {
			return manifest, fmt.Errorf("%s: volume image must be exactly 256 MiB", member)
		}
		config := object(record["guest_config"])
		if e = ValidateManagedConfig(member, config, inputs); e != nil {
			return manifest, e
		}
		s3, e := SignedS3Config(member, inputs["signed_v2_s3_config"])
		if e != nil {
			return manifest, e
		}
		manifest.Members[member] = ManagedMember{inputs, config, s3}
	}
	a, b := manifest.Members["a"], manifest.Members["b"]
	for _, key := range []string{"cluster_id", "tenant_id", "database_id", "shard_id"} {
		if !jsonEqual(object(object(a.Config["member"])["scope"])[key], object(object(b.Config["member"])["scope"])[key]) {
			return manifest, errors.New("members are not in one signed shard")
		}
	}
	for _, key := range []string{"epoch", "configuration_id", "certificate_sha256"} {
		if !jsonEqual(object(a.Config["authority"])[key], object(b.Config["authority"])[key]) {
			return manifest, errors.New("members disagree on signed authority")
		}
	}
	for _, key := range []string{"source_digest", "system_reserve_bytes", "collection_id", "schema_generation", "schema_digest", "document_id"} {
		if !jsonEqual(a.Config[key], b.Config[key]) {
			return manifest, errors.New("members disagree on transaction fixture")
		}
	}
	if !jsonEqual(a.S3, b.S3) {
		return manifest, errors.New("members disagree on signed S3 target")
	}
	return manifest, nil
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func ReadS3Credential(path string) (string, error) {
	if !filepath.IsAbs(path) {
		return "", errors.New("S3 credential path must be absolute")
	}
	before, e := os.Lstat(path)
	if e != nil {
		return "", e
	}
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC|unix.O_NONBLOCK, 0)
	if e != nil {
		return "", e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	info, e := f.Stat()
	if e != nil {
		return "", e
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !info.Mode().IsRegular() || !os.SameFile(before, info) || !ok || (owner.Uid != 0 && owner.Uid != uint32(os.Getuid())) || info.Mode().Perm() != 0o600 || info.Size() <= 0 || info.Size() > 1024 {
		return "", errors.New("S3 credential file has unsafe ownership, mode or size")
	}
	b, e := io.ReadAll(io.LimitReader(f, 1025))
	if e != nil {
		return "", e
	}
	after, e := f.Stat()
	if e != nil {
		return "", e
	}
	if int64(len(b)) != info.Size() || !after.ModTime().Equal(info.ModTime()) {
		return "", errors.New("S3 credential file changed while reading")
	}
	for _, c := range b {
		if c < 0x21 || c > 0x7e {
			return "", errors.New("S3 credential file contains invalid bytes")
		}
	}
	return string(b), nil
}
func S3Credentials(paths [2]string) ([2]string, error) {
	var values [2]string
	for i, p := range paths {
		v, e := ReadS3Credential(p)
		if e != nil {
			return values, e
		}
		if !regexp.MustCompile(`^[A-Za-z0-9_-]+$`).MatchString(v) {
			return values, errors.New("S3 fixture credentials must use ASCII letters, digits, '-' or '_'")
		}
		values[i] = v
	}
	return values, nil
}
func S3TargetDigest(region, bucket, endpoint string) string {
	b := []byte("terrabase-s3-target-v1\x00")
	for _, v := range []string{region, bucket, endpoint} {
		b = binary.BigEndian.AppendUint64(b, uint64(len(v)))
		b = append(b, []byte(v)...)
	}
	return hashBytes(b)
}

func SignedS3Config(member string, r ManagedInput) (Object, error) {
	if r.Size <= 0 || r.Size > 16<<10 {
		return nil, fmt.Errorf("%s: signed S3 config size invalid", member)
	}
	before, e := os.Lstat(r.Path)
	if e != nil {
		return nil, e
	}
	fd, e := unix.Open(r.Path, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if e != nil {
		return nil, e
	}
	f := os.NewFile(uintptr(fd), r.Path)
	defer f.Close()
	opened, e := f.Stat()
	if e != nil {
		return nil, e
	}
	if !opened.Mode().IsRegular() || !os.SameFile(before, opened) {
		return nil, fmt.Errorf("%s: signed S3 config is not a direct regular file", member)
	}
	raw, e := io.ReadAll(io.LimitReader(f, (16<<10)+1))
	if e != nil {
		return nil, e
	}
	after, e := f.Stat()
	if e != nil {
		return nil, e
	}
	if int64(len(raw)) != r.Size || opened.Size() != after.Size() || !opened.ModTime().Equal(after.ModTime()) || hashBytes(raw) != r.SHA256 {
		return nil, fmt.Errorf("%s: signed S3 config changed", member)
	}
	v, e := decodeStrict(raw)
	if e != nil {
		return nil, fmt.Errorf("%s: signed S3 config is not JSON: %w", member, e)
	}
	c := object(v)
	if !exactFields(c, []string{"version", "ack_profile", "bucket", "region", "endpoint"}) || !exactValue(c["version"], 1) || c["ack_profile"] != "object_durable" || c["region"] != S3Region || c["endpoint"] != S3Endpoint || !regexp.MustCompile(`^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$`).MatchString(str(c["bucket"])) || strings.Contains(str(c["bucket"]), "..") {
		return nil, fmt.Errorf("%s: signed S3 target is invalid", member)
	}
	// Preserve exporter field order while requiring its exact JSON string and number encodings.
	decoder := jsontext.NewDecoder(bytes.NewReader(raw))
	_, _ = decoder.ReadToken()
	var canonical bytes.Buffer
	canonical.WriteByte('{')
	first := true
	for decoder.PeekKind() != '}' {
		key, err := decoder.ReadToken()
		if err != nil {
			return nil, err
		}
		name := key.String()
		if _, err = decoder.ReadValue(); err != nil {
			return nil, err
		}
		if !first {
			canonical.WriteByte(',')
		}
		first = false
		encodedKey, err := json.Marshal(name)
		if err != nil {
			return nil, err
		}
		encodedValue, err := json.Marshal(strictToJSON(c[name]))
		if err != nil {
			return nil, err
		}
		canonical.Write(encodedKey)
		canonical.WriteByte(':')
		canonical.Write(encodedValue)
	}
	canonical.WriteByte('}')
	if !bytes.Equal(raw, canonical.Bytes()) {
		return nil, fmt.Errorf("%s: signed S3 config is not canonical exporter JSON", member)
	}
	return c, nil
}

func GuestPath(mount, destination string) (string, error) {
	if !filepath.IsAbs(destination) || slices.Contains(strings.Split(destination, "/"), "..") {
		return "", fmt.Errorf("unsafe guest path %s", destination)
	}
	current := mount
	parts := strings.Split(strings.TrimPrefix(destination, "/"), "/")
	for i, part := range parts {
		if part == "" {
			continue
		}
		current = filepath.Join(current, part)
		s, e := os.Lstat(current)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return "", e
		}
		if s.Mode()&os.ModeSymlink != 0 {
			return "", fmt.Errorf("guest path traverses symlink %s", current)
		}
		if i < len(parts)-1 && !s.IsDir() {
			return "", fmt.Errorf("guest path parent is not a directory: %s", current)
		}
	}
	return current, nil
}
func CheckManagedGuestTools(mount string) error {
	for _, tool := range []string{"/usr/lib/systemd/systemd", "/usr/sbin/blkid", "/usr/sbin/update-ca-certificates", "/usr/bin/mount", "/usr/bin/findmnt", "/usr/bin/mountpoint", "/usr/bin/readlink", "/usr/bin/systemctl", "/usr/bin/ip"} {
		p, e := GuestPath(mount, tool)
		if e != nil {
			return e
		}
		s, e := os.Stat(p)
		if e != nil || !s.Mode().IsRegular() {
			return fmt.Errorf("guest rootfs lacks %s", tool)
		}
	}
	return nil
}

func (w *BoundedWriter) Write(b []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	remaining := max(int64(0), w.Limit-w.Total)
	w.Total += int64(len(b))
	if remaining > 0 {
		if _, e := w.File.Write(b[:min(int64(len(b)), remaining)]); e != nil {
			return 0, e
		}
	}
	return len(b), nil
}
func (w *BoundedWriter) Overflowed() bool { w.mu.Lock(); defer w.mu.Unlock(); return w.Total > w.Limit }
func (w *BoundedWriter) Close() error     { return w.File.Close() }
func BoundedCommand(ctx context.Context, argv []string, o CommandOptions, path string, bound int64) (CommandResult, error) {
	r, _, err := runBoundedCommand(ctx, argv, o, path, bound, nil)
	return r, err
}
func runBoundedCommand(ctx context.Context, argv []string, o CommandOptions, path string, bound int64, hooks *processHooks) (CommandResult, *Process, error) {
	if len(argv) == 0 {
		return CommandResult{}, nil, errors.New("empty command")
	}
	if err := ctx.Err(); err != nil {
		return CommandResult{}, nil, err
	}
	file, e := os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if e != nil {
		return CommandResult{}, nil, e
	}
	capture := &BoundedWriter{File: file, Limit: bound}
	c := exec.Command(argv[0], argv[1:]...)
	c.Dir = o.Dir
	c.Env = o.Env
	c.Stdin = strings.NewReader(o.Input)
	c.Stdout = capture
	c.Stderr = capture
	c.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	c.WaitDelay = 2 * time.Second
	if e = c.Start(); e != nil {
		file.Close()
		return CommandResult{}, nil, e
	}
	p := &Process{Cmd: c, Output: capture, hooks: hooks}
	waitErr := waitCommand(ctx, p, o.Timeout)
	cleanup := p.Stop(10*time.Second, true)
	b, readErr := os.ReadFile(path)
	r := CommandResult{Code: p.ExitCode, Stdout: string(b)}
	if capture.Overflowed() {
		waitErr = errors.Join(waitErr, fmt.Errorf("command log exceeded %d bytes", bound))
	}
	if e = errors.Join(waitErr, cleanup, readErr); e != nil {
		if !p.Reaped {
			return r, p, &PendingCommandError{Process: p, Err: e}
		}
		return r, nil, e
	}
	if r.Code != 0 && !o.AllowFailure {
		return r, nil, fmt.Errorf("command failed (%d): %q; log: %s: %s", r.Code, argv, path, tail(r.Stdout, 1500))
	}
	return r, nil, nil
}

func waitCommand(ctx context.Context, p *Process, timeout time.Duration) error {
	if timeout <= 0 {
		timeout = 120 * time.Second
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		done, err := p.Exited()
		if err != nil || done {
			return err
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(25 * time.Millisecond):
		}
	}
}

func (p *Process) Exited() (bool, error) {
	if p.Reaped {
		return true, nil
	}
	if p.hooks != nil && p.hooks.exited != nil {
		return p.hooks.exited()
	}
	var info unix.Siginfo
	e := unix.Waitid(unix.P_PID, p.PID(), &info, unix.WEXITED|unix.WNOHANG|unix.WNOWAIT, nil)
	if e != nil {
		return false, fmt.Errorf("owned process %d was reaped before cleanup: %w", p.PID(), e)
	}
	return info.Signo != 0, nil
}
func (p *Process) Group() (int, error) {
	if p.Reaped {
		return 0, fmt.Errorf("owned process %d was reaped before group cleanup", p.PID())
	}
	group := syscall.Getpgid
	if p.hooks != nil && p.hooks.group != nil {
		group = p.hooks.group
	}
	id, e := group(p.PID())
	if e != nil {
		return 0, e
	}
	if id != p.PID() {
		return 0, fmt.Errorf("owned process %d is no longer its process-group leader", p.PID())
	}
	return id, nil
}
func LiveProcessGroupMembers(pgid int) ([]int, error) {
	entries, e := os.ReadDir("/proc")
	if e != nil {
		return nil, e
	}
	members := []int{}
	for _, entry := range entries {
		pid, e := strconv.Atoi(entry.Name())
		if e != nil {
			continue
		}
		b, e := os.ReadFile(filepath.Join("/proc", entry.Name(), "stat"))
		if processStatGone(e) {
			continue
		}
		if e != nil {
			return nil, e
		}
		_, after, ok := strings.CutLast(string(b), ")")
		if !ok {
			return nil, fmt.Errorf("invalid process status for %d", pid)
		}
		f := strings.Fields(after)
		if len(f) < 3 {
			return nil, fmt.Errorf("invalid process status for %d", pid)
		}
		id, e := strconv.Atoi(f[2])
		if e != nil {
			return nil, e
		}
		if id == pgid && !slices.Contains([]string{"Z", "X", "x"}, f[0]) {
			members = append(members, pid)
		}
	}
	return members, nil
}

// A process can disappear after its stat file opens, returning ESRCH instead of ENOENT.
func processStatGone(err error) bool {
	return errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ESRCH)
}

func WaitProcessGroupQuiescent(pgid int, timeout time.Duration) error {
	deadline := time.Now().Add(timeout)
	for {
		members, e := LiveProcessGroupMembers(pgid)
		if e != nil {
			return e
		}
		if len(members) == 0 {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("owned process group %d still has live members: %v", pgid, members)
		}
		time.Sleep(50 * time.Millisecond)
	}
}
func (p *Process) WaitUnreaped(timeout time.Duration) (bool, error) {
	if p.hooks != nil && p.hooks.wait != nil {
		return p.hooks.wait(timeout)
	}
	deadline := time.Now().Add(timeout)
	for {
		done, e := p.Exited()
		if e != nil || done {
			return done, e
		}
		if time.Now().After(deadline) {
			return false, nil
		}
		time.Sleep(50 * time.Millisecond)
	}
}
func (p *Process) Stop(timeout time.Duration, kill bool) error {
	id, e := p.Group()
	if e != nil {
		return e
	}
	if !kill {
		if e = p.signalGroup(id, syscall.SIGTERM); e != nil && !errors.Is(e, syscall.ESRCH) {
			return e
		}
		if _, e = p.WaitUnreaped(timeout); e != nil {
			return e
		}
		if _, e = p.Group(); e != nil {
			return e
		}
	}
	if e = p.signalGroup(id, syscall.SIGKILL); e != nil && !errors.Is(e, syscall.ESRCH) {
		return e
	}
	quiescent := WaitProcessGroupQuiescent
	if p.hooks != nil && p.hooks.quiescent != nil {
		quiescent = p.hooks.quiescent
	}
	if e = quiescent(id, timeout); e != nil {
		return e
	}
	if p.hooks != nil && p.hooks.reap != nil {
		e = p.hooks.reap()
	} else {
		e = p.Cmd.Wait()
	}
	p.Reaped = true
	if p.Cmd.ProcessState != nil {
		p.ExitCode = p.Cmd.ProcessState.ExitCode()
	}
	if _, ok := errors.AsType[*exec.ExitError](e); ok {
		e = nil
	}
	if p.Output != nil {
		e = errors.Join(e, p.Output.Close())
		p.Output = nil
	}
	return e
}
func (p *Process) signalGroup(id int, signal syscall.Signal) error {
	if p.hooks != nil && p.hooks.signal != nil {
		return p.hooks.signal(id, signal)
	}
	return syscall.Kill(-id, signal)
}

